import{_ as e,o as t,c as n,ag as r}from"./chunks/framework.Dx86EdC1.js";const p=JSON.parse('{"title":"Pengguna, Role & Hak Akses","description":"","frontmatter":{},"headers":[],"relativePath":"panduan-pengguna/pengguna-role.md","filePath":"panduan-pengguna/pengguna-role.md","lastUpdated":1791382762000}'),d={name:"panduan-pengguna/pengguna-role.md"};function s(o,a,i,l,u,c){return t(),n("div",null,[...a[0]||(a[0]=[r('<h1 id="pengguna-role-hak-akses" tabindex="-1">Pengguna, Role &amp; Hak Akses <a class="header-anchor" href="#pengguna-role-hak-akses" aria-label="Permalink to &quot;Pengguna, Role &amp; Hak Akses&quot;">​</a></h1><p>Menu ini hanya terbuka untuk <strong>Superadmin</strong> (<code>/admin/users</code> dan <code>/admin/roles</code>).</p><h2 id="pengguna-admin-users" tabindex="-1">Pengguna (<code>/admin/users</code>) <a class="header-anchor" href="#pengguna-admin-users" aria-label="Permalink to &quot;Pengguna (`/admin/users`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Aksi</th><th>Keterangan</th></tr></thead><tbody><tr><td>Tambah</td><td>Buat akun: nama, username, email, kata sandi, role, status aktif</td></tr><tr><td>Edit</td><td>Ubah data &amp; role</td></tr><tr><td>Toggle status</td><td>Aktif/nonaktifkan akun (<code>PATCH /admin/users/{id}/toggle-status</code>)</td></tr><tr><td>Hapus</td><td>Hapus akun (data warga terkait tidak ikut terhapus)</td></tr></tbody></table><h2 id="role-bawaan" tabindex="-1">Role Bawaan <a class="header-anchor" href="#role-bawaan" aria-label="Permalink to &quot;Role Bawaan&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Role</th><th>Kegunaan</th></tr></thead><tbody><tr><td><code>superadmin</code></td><td>Akses penuh + manajemen pengguna/role</td></tr><tr><td><code>kades</code></td><td>Persetujuan &amp; TTE surat, monitoring, konten</td></tr><tr><td><code>perangkat</code></td><td>Operator: kependudukan, proses surat, template, konten</td></tr><tr><td><code>rt</code></td><td>Verifikasi surat RT (terbatas pada wilayahnya)</td></tr><tr><td><code>warga</code></td><td>Layanan mandiri (tanpa akses <code>/admin</code>)</td></tr></tbody></table><h2 id="matriks-permission-admin-roles-role" tabindex="-1">Matriks Permission (<code>/admin/roles/{role}</code>) <a class="header-anchor" href="#matriks-permission-admin-roles-role" aria-label="Permalink to &quot;Matriks Permission (`/admin/roles/{role}`)&quot;">​</a></h2><p>Superadmin dapat menambah/mengurangi permission per role melalui <strong>Role → Ubah Permission</strong>:</p><ul><li><code>admin.access</code>, <code>users.manage</code>, <code>settings.manage</code></li><li><code>residents.view</code>, <code>residents.manage</code></li><li><code>letters.request</code>, <code>letters.verify_rt</code>, <code>letters.process</code>, <code>letters.approve</code>, <code>letters.manage_templates</code></li><li><code>contents.manage</code>, <code>reports.view</code></li></ul><div class="warning custom-block"><p class="custom-block-title">Hati-hati</p><p>Mencabut <code>admin.access</code> membuat role tersebut <strong>tidak bisa masuk dashboard</strong>. Selalu uji dengan akun percobaan setelah mengubah matriks.</p></div><h2 id="pembatasan-berbasis-wilayah" tabindex="-1">Pembatasan Berbasis Wilayah <a class="header-anchor" href="#pembatasan-berbasis-wilayah" aria-label="Permalink to &quot;Pembatasan Berbasis Wilayah&quot;">​</a></h2><p>Akun RT otomatis dibatasi:</p><ul><li>Daftar &amp; detail KK/penduduk hanya di RT/RW yang ditugaskan (field <code>rt</code>, <code>rw</code> pada user).</li><li>Membuka KK di luar wilayahnya → <strong>403</strong> &quot;Akses Ditolak&quot;.</li><li>Hanya bisa memproses permohonan surat status <code>pending_rt</code>.</li></ul><p>Pembatasan ini bersifat <strong>query-level</strong> (bukan sekadar sembunyikan menu), sesuai prinsip UU PDP.</p><h2 id="rekomendasi-praktik" tabindex="-1">Rekomendasi Praktik <a class="header-anchor" href="#rekomendasi-praktik" aria-label="Permalink to &quot;Rekomendasi Praktik&quot;">​</a></h2><ul><li>Satu akun untuk satu orang; jangan berbagi akun operator.</li><li>Aktifkan username unik untuk login selain email.</li><li>Nonaktifkan akun saat pekerja berpindah tugas.</li><li>Seluruh perubahan pengguna tercatat di <a href="/panduan-pengguna/audit-log.html">Audit Log</a>.</li></ul>',16)])])}const k=e(d,[["render",s]]);export{p as __pageData,k as default};
